CustomField.formula:
IF(
ISBLANK(Employee__r.Termination_date__c),
FISAA_Yearly_Target__c / 12,  
FISAA_Yearly_Target__c / (
(MONTH(
IF(Target_date__c > DATE(YEAR(Target_date__c), 12, 31),
DATE(YEAR(Target_date__c), 12, 31),
Employee__r.Termination_date__c
)
)
-
MONTH(
IF( Employee__r.Onboarding_date__c < DATE(YEAR(Target_date__c), 1, 1),
DATE(YEAR(Target_date__c), 1, 1),
Employee__r.Onboarding_date__c
)
)
+ 1)
)
)
